script:
roteiro 0.1 {
  // Marcadores manuais, futuramente associados à locução do Estúdio.
  marca introducao 0.5s
  marca relacoes 3s
  marca conclusao 9s
  em introducao {
    paralelo {
      aparecer rede durante 0.65s
      mover rede para [0,0,0] durante 1.4s
      aparecer titulo durante 0.8s
      efeito pulso durante 0.18s
    }
  }
  em relacoes {
    paralelo {
      sequencia {
        girar rede para [60,160,15] durante 2s
        girar rede para [20,390,0] durante 3s
      }
      sequencia {
        mover cam para [0,0,10] durante 1.5s
        esperar 1s
        mover cam para [0,0,14] durante 2s
      }
      aparecer legenda durante 0.6s
      efeito pulso durante 0.16s
    }
  }
  em conclusao {
    paralelo {
      mover rede para [3,0,0] durante 2s
      desaparecer rede durante 2s
      desaparecer titulo durante 1s
      desaparecer legenda durante 1.5s
      efeito pulso durante 0.2s
    }
  }
}
